// Üretilen dosya: tool/ozgun/uret.py. Bilişim ve Algoritmalar · Düzenli ifadeler (regex), sonlu durum makineleri, özyineleme (recursion) izleme, yığınla ifade değerlendirme ve derleyici aşamaları (kolay).
const ozComputing16Kolay = <(String, String, List<String>, String)>[
  ('Düzenli ifadelerde kullanılan \'\$\' (dolar) çıpa karakterinin temel görevi nedir?', 'Dizgenin veya satırın son konumunu eşleştirmek', ['Yalnızca sayısal para birimi simgelerini seçmek', 'Önceki karakterin en az bir kez tekrarını sağlamak', 'Boşluk dışındaki tüm özel sembolleri maskelemek'], 'Dolar (\$) çıpası, desenin satır ya da metin sonunda bitmesini denetler.'),
  ('Çok satırlı olmayan varsayılan modda \'k.t\' düzenli ifadesi aşağıdaki dizgelerden hangisiyle eşleşmez?', 'kntt', ['kat', 'k9t', 'k_t'], 'Nokta (.) tek bir karakterin yerini tutar; \'kntt\' dizgesinde k ile son t arasında iki karakter vardır ve tamamı 4 harflidir.'),
  ('Bir form alanında \'renk\' ve \'renkli\' kelimelerinin ikisini birden kabul edip \'renksiz\' veya \'renkliler\' kelimelerini dışlamak için \'^renk(li)?\$\' ifadesindeki \'?\' niceleyicisi ne sağlar?', 'Önceki grubun sıfır veya bir kez bulunmasına izin verir', ['Önceki grubun en az iki defa tekrarlanmasını şart koşar', 'Grubun içindeki harflerin sırasını rastgele değiştirir', 'Büyük ve küçük harf duyarlılığını tamamen devre dışı bırakır'], 'Soru işareti (?) niceleyicisi kendinden önceki öğeyi isteğe bağlı (0 veya 1 kez) yapar.'),
  ('Aşağıdaki dizgelerden hangisi \'^ab*c\$\' düzenli ifadesinin tanımladığı dilin bir elemanıdır?', 'ac', ['abcde', 'abbc_c', 'babc'], 'Yıldız (*) niceleyicisi \'b\' harfinin 0 veya daha fazla kez geçmesine izin verdiğinden \'ac\' geçerli bir eşleşmedir.'),
  ('Kullanıcı adı doğrulamasında \'^go+gle\$\' deseni kullanıldığında hangi girdi reddedilir?', 'ggle', ['google', 'gogle', 'gooooogle'], 'Artı (+) niceleyicisi kendinden önceki \'o\' karakterinin en az 1 kez bulunmasını zorunlu kılar; \'ggle\' içinde \'o\' yoktur.'),
  ('Türkiye\'deki 5 haneli posta kodlarını tam olarak doğrulamak isteyen bir yazılımcı hangi düzenli ifadeyi tercih etmelidir?', '^[0-9]{5}\$', ['^[0-9]{1,5}\$', '[0-9]+', '^\\w{5}\$'], 'Başlangıç ve bitiş çıpalarıyla birlikte {5} niceleyicisi tam 5 rakamdan oluşan girdileri kabul eder.'),
  ('Köşeli parantez içinde ilk karakter olarak kullanılan \'^\' işareti (örneğin \'[^0-9]\') düzenli ifadede nasıl yorumlanır?', 'Belirtilen küme dışındaki herhangi bir karakterle eşleşir', ['Yalnızca satır başındaki rakam dizilerini yakalar', 'Rakamların artan sırada dizilmesini zorunlu tutar', 'Köşeli parantezin kendisini düz metin olarak arar'], 'Karakter sınıfının başındaki \'^\' olumsuzlama (negation) anlamı taşır ve listede olmayan tek bir karakteri seçer.'),
  ('Standart ASCII tabanlı düzenli ifade motorlarında \'\\w\' kısayolu hangi karakter kümesine karşılık gelir?', '[A-Za-z0-9_]', ['[A-Za-z ]', '[0-9+-*/]', '[^ \\t\\n\\r]'], 'Kelime karakteri kısayolu olan \\w; büyük-küçük İngilizce harfleri, rakamları ve alt çizgi (_) karakterini kapsar.'),
  ('Bir günlük (log) dosyasında boşluk, sekme (tab) ve satır sonu karakterlerinin tümünü tek bir kısayolla yakalamak için ne kullanılır?', '\\s', ['\\d', '\\b', '\\W'], '\\s kısayolu boşluk (whitespace) karakterleri olan boşluk, \\t, \\n ve \\r gibi ayırıcıları temsil eder.'),
  ('Parola politikasında kullanıcı adının en az 4, en fazla 12 alfanümerik veya alt çizgi karakterinden oluşmasını denetleyen düzenli ifade hangisidir?', '^\\w{4,12}\$', ['^\\w{4-12}\$', '\\w[4,12]', '^[a-z]{4,12}\$'], 'Süslü parantez içinde virgülle ayrılan {4,12} alt ve üst tekrar sınırlarını belirtir; \\w alfanümerik ve alt çizgiyi kapsar.'),
  ('Düzenli ifadede \'\\D\' meta dizisi aşağıdakilerden hangisiyle eşdeğerdir?', '[^0-9]', ['[0-9]', '[a-zA-Z]', '[^a-zA-Z0-9_]'], 'Büyük harfli kısayollar küçük harflilerin tümleyenidir; \\d rakam iken \\D rakam olmayan tek bir karakterdir.'),
  ('Onaltılık (hexadecimal) 6 haneli CSS renk kodlarını (örneğin \'#1A2b3F\' veya \'#00ff99\') doğrulamak için hangi düzenli ifade eksiksizdir?', '^#[0-9A-Fa-f]{6}\$', ['^#[0-9A-Z]{6}\$', '#[0-9a-f]{1,6}', '^#[\\d\\w]{6}\$'], 'Onaltılık taban yalnızca 0-9 rakamlarını ve A-F (büyük/küçük) harflerini içerir; G-Z harfleri geçersizdir.'),
  ('Metin içindeki \'C++\' programlama dili adını düz metin olarak aramak isteyen bir araştırmacı hangi düzenli ifadeyi yazmalıdır?', 'C\\+\\+', ['C++', 'C(+)(+)', 'C\\+2'], 'Artı (+) niceleyici bir meta karakter olduğundan edebi artı simgesiyle eşleşmek için ters eğik çizgiyle kaçırılmalıdır.'),
  ('Aşağıdaki dizgelerden hangisi \'^(0|1)*00\$\' düzenli ifadesiyle eşleşir?', '101100', ['0010', '1010', '0'], 'Desen sıfır ve birlerden oluşan ve son iki karakteri kesinlikle \'00\' olan tüm ikili dizgeleri tanımlar.'),
  ('Niceleyici biçimlerinden \'{3,}\' ifadesi kendinden önceki öğe için ne anlama gelir?', 'Öğenin alt sınırı 3 olmak üzere üst sınırsız sayıda tekrarlanabileceği', ['Öğenin en fazla 3 kez geçebileceği ve boş dizgeyi de kapsadığı', 'Öğenin yalnızca 3\'ün tam katları kadar tekrarlanabileceği', 'Öğeden sonra en az bir virgül karakterinin gelmesi gerektiği'], '{m,} yazılışında üst sınır boş bırakıldığında \'en az m kez, sonsuza kadar\' anlamı taşır.'),
  ('Bilimsel gösterimsiz ondalıklı sayıları (örneğin \'3.14\', \'0.5\', \'120.75\' ama \'.5\' veya \'12.\' değil) doğrulayan desen hangisidir?', '^\\d+\\.\\d+\$', ['^\\d*\\.\\d*\$', '^\\d+.\\d+\$', '^[0-9]+,[0-9]*\$'], 'Noktanın her iki yanında en az birer rakam bulunması için \'\\d+\' ve gerçek nokta için \'\\.\' kullanılmalıdır.'),
  ('Kaynak koddaki tek satırlık \'//\' yorumlarını satır sonuna kadar seçmek isteyen bir araç (çok satırlı mod açıkken) hangi deseni kullanmalıdır?', '//.*\$', ['//.+\\n+', '/\\*.*\\*/', '^//\\w+\$'], 'Normal modda \'.\' satır sonu hariç tüm karakterleri eşlediğinden \'//.*\$\' ifadesi \'//\' işaretinden satır sonuna kadar her şeyi yakalar.'),
  ('Aşağıdaki dizgelerden hangisi \'^a(bc)+d?\$\' düzenli ifadesi tarafından kabul edilir?', 'abcbc', ['ad', 'abcbdd', 'abccbd'], '\'a\' ile başlamalı, \'bc\' bloğu en az bir kez tekrarlanmalı (burada iki kez: bcbc) ve \'d\' sıfır ya da bir kez gelmelidir.'),
  ('Bir dizgede en az bir kez \'00\' alt dizgesi içeren tüm ikili dizgeleri tanımlayan düzenli ifade hangisidir?', '^[01]*00[01]*\$', ['^00[01]+\$', '^(00)+\$', '^1*001*\$'], 'Başta ve sonda istenildiği kadar 0 veya 1 bulunabilir; ortadaki zorunlu \'00\' alt dizgenin en az bir kez geçmesini garanti eder.'),
  ('Bir fatura numarasının \'FTR-\' ile başlayıp ardından 4 haneli yıl, tire ve en az 1 en fazla 6 haneli sıra numarası (\'FTR-2021-45\' gibi) içermesini doğrulayan ifade hangisidir?', '^FTR-\\d{4}-\\d{1,6}\$', ['^FTR-\\d{4}-\\d{6}\$', 'FTR-[0-9]{4}-[0-9]*', '^(FTR)-\\d{4,6}\$'], 'Sabit \'FTR-\' öneki, 4 rakamlı yıl \'\\d{4}\', tire ve 1 ila 6 rakamlı sıra numarası \'\\d{1,6}\' çıpalarla tam eşleştirilir.'),
  ('Büyük/küçük harf duyarsız (\'i\' - case-insensitive) bayrağı açıkken \'^[a-c]{3}\$\' ifadesi aşağıdaki dizgelerden hangisini kabul eder?', 'BaC', ['Abd', 'abcc', 'A1c'], '\'i\' bayrağı etkin olduğunda [a-c] aralığı [a-cA-C] gibi davranır ve 3 karakterli \'BaC\' dizgesini eşleştirir.'),
  ('\'ab+c\' ile \'(ab)+c\' düzenli ifadelerinin ürettiği diller arasındaki fark hangi seçenekte doğru açıklanmıştır?', 'İlki yalnız \'b\' harfini tekrarlarken (\'abbbc\'), ikincisi \'ab\' ikilisini bütün olarak tekrarlar', ['İlki boş dizgeyi kabul ederken ikincisi en az dört karakterli dizgeleri kabul eder', 'Her iki ifade de birebir aynı dizge kümesini üretir ancak ikincisi daha hızlı çalışır', 'İlki \'c\' harfini isteğe bağlı yaparken ikincisi \'a\' harfini isteğe bağlı yapar'], 'Niceleyiciler parantez yoksa yalnız hemen solundaki tek karaktere (\'b\') bağlanır; parantez ise tüm \'ab\' dizisini kapsar.'),
  ('\'^[0-9]{2,4}\$\' deseni aşağıdaki sayı dizgelerinden hangisini reddeder?', '7', ['42', '305', '1998'], '{2,4} niceleyicisi en az 2, en fazla 4 rakam şartı koyduğundan tek basamaklı \'7\' dizgesini kabul etmez.'),
  ('Bir metin ayrıştırıcıda \'\\S+\' düzenli ifadesi uygulandığında metin nasıl parçalara ayrılır?', 'Boşluk olmayan ardışık karakter blokları (kelimeler ve bitişik noktalama işaretleri) seçilir', ['Yalnızca ardışık boşluk, sekme ve satır sonu dizileri tek tek listelenir', 'Harf dışındaki tüm özel karakterler ve rakamlar metinden ayıklanır', 'Cümleler yalnızca nokta ve soru işareti sınırlarından bölünür'], '\\S boşluk olmayan karakter demektir; \\S+ ise boşluklarla ayrılmış her bir dolu karakter kümesini (token) yakalar.'),
  ('Deterministik bir sonlu durum otomatının (DFA) matematiksel beşli tanımında (Q, Σ, δ, q0, F) yer alan \'Σ\' simgesi neyi gösterir?', 'Girdi alfabesini oluşturan sonlu semboller kümesini', ['Makinenin çalışmaya başladığı tekil başlangıç durumunu', 'Geçiş fonksiyonunun ürettiği tüm olası durum çiftlerini', 'Dizge okunduğunda kabul kararı verilen uç durumların listesini'], 'Beşli tanımda Q durumlar kümesini, Σ girdi alfabesini, δ geçiş fonksiyonunu, q0 başlangıç durumunu ve F kabul durumları kümesini belirtir.'),
  ('Bir sonlu durum makinesinin diyagramında çift iç içe çemberle çizilen düğümler hangi kavramı temsil eder?', 'Kabul (uç) durumlarını', ['Geri dönüşü olmayan tuzak durumlarını', 'Boş dizge geçişine sahip ara durumları', 'Dışarıdan okla işaretlenen başlangıç durumunu'], 'Otomat diyagramlarında başlangıç durumu dışarıdan gelen boşta bir okla, kabul (accept/final) durumları ise çift çemberle gösterilir.'),
  ('Deterministik sonlu otomat (DFA) ile deterministik olmayan sonlu otomat (NFA) arasındaki temel yapısal fark nedir?', 'DFA\'da her durum ve her alfabe sembolü için tam olarak bir hedef durum tanımlıdır', ['DFA sınırsız bir yığın belleğine sahipken NFA yalnızca sabit yazmaç kullanır', 'NFA bağlamdan bağımsız dilleri tanıyabilirken DFA yalnızca düzenli dilleri tanır', 'DFA birden fazla başlangıç durumuna izin verirken NFA tek kabul durumu içerir'], 'DFA\'da belirsizlik yoktur: her (durum, sembol) çifti için tam bir geçiş bulunur ve ε-geçişi yer almaz.'),
  ('Bir metro turnikesi \'Kilitli\' ve \'Açık\' olmak üzere iki duruma sahiptir. Başlangıçta \'Kilitli\' olan turnikeye sırasıyla \'Jeton At\', \'Jeton At\', \'İt\', \'İt\' girdileri uygulandığında son durum ne olur?', 'Kilitli durumunda kalır', ['Açık durumunda kalarak ikinci geçişe izin verir', 'Arıza durumuna geçerek jeton iadesi başlatır', 'Belirsiz duruma düşerek her iki kolu da serbest bırakır'], 'İlk jeton turnikeyi \'Açık\' yapar, ikinci jeton açıkken durumu değiştirmez (\'Açık\' kalır), ilk \'İt\' geçiş yaptırıp \'Kilitli\'ye döndürür, ikinci \'İt\' kilitliyken durumu değiştirmez.'),
  ('İkili bir dizgede \'1\' rakamının çift sayıda (0, 2, 4...) geçip geçmediğini denetleyen en küçük DFA kaç duruma ihtiyaç duyar?', '2 durum', ['1 durum', '3 durum', 'Dizgenin bit uzunluğu kadar durum'], 'Yalnızca parite bilgisi (\'şimdiye kadar çift sayıda 1 görüldü\' = q_cift başlangıç/kabul ve \'tek sayıda 1 görüldü\' = q_tek) tutulduğundan 2 durum yeterlidir.'),
  ('NFA\'larda bulunan ε-geçişi (epsilon transition) makinenin çalışmasında nasıl bir davranışa izin verir?', 'Girdi bandından hiçbir karakter tüketmeden kendiliğinden başka bir duruma geçebilmesine', ['Alfabe dışında kalan bozuk karakterleri silerek dizgeyi onarmasına', 'Makinenin girdi dizgesini sağdan sola doğru geriye sararak okumasına', 'Tüm kabul durumlarını tek bir adımda başlangıç durumuna dönüştürmesine'], 'Epsilon (ε) boş dizgeyi simgeler; ε-geçişi sıradaki girdi harfini okumadan durum değiştirmeyi sağlar.'),
  ('Bir DFA\'da içine girildiğinde hiçbir girdi dizisiyle bir daha kabul durumuna çıkılamayan ve tüm harflerde kendi kendine dönen duruma ne ad verilir?', 'Tuzak (ölü / sink) durum', ['Başlangıç durumu', 'Kararsız (metastable) durum', 'Epsilon köprü durumu'], 'Önek bazlı bir kural kesin olarak bozulduğunda (örneğin \'a ile başlamalı\' kuralında ilk harf \'b\' geldiğinde) DFA geri kalan girdiyi tüketmek için tuzak duruma geçer.'),
  ('{0, 1} alfabesinde son karakteri \'1\' olan dizgeleri tanıyan en küçük DFA kaç durumludur?', '2 durum', ['1 durum', '3 durum', '4 durum'], 'Yalnızca son görülen bitin \'1\' olup olmadığı önemlidir: q0 (başlangıç / son bit 1 değil) ve q1 (son bit 1, kabul); her \'0\' q0\'a, her \'1\' q1\'e götürür.'),
  ('Bir oyun karakterinin yapay zekâsı \'Devriye\', \'Kovalama\' ve \'Saklanma\' durumlarıyla modellenmiştir. Karakter \'Kovalama\' durumundayken \'Can < %20\' olayı gerçekleşirse \'Saklanma\'ya, \'Oyuncu Menzilden Çıktı\' olayı gerçekleşirse \'Devriye\'ye geçmektedir. Bu modelde geçişleri tetikleyen koşullara ne denir?', 'Olay / Muhafız koşulu (event / guard)', ['Sözdizimi jetonu (lexical token)', 'Çağrı yığını çerçevesi (stack frame)', 'Taban durum (base case)'], 'Uygulamalı sonlu durum makinelerinde (FSM) durum değişimini başlatan dış uyaranlara olay (event), ek mantıksal şartlara muhafız koşulu (guard) denir.'),
  ('Bir asansör kapısı denetleyicisi \'Kapalı\', \'Açılıyor\', \'Açık\' ve \'Kapanıyor\' durumlarına sahiptir. Kapı \'Kapanıyor\' durumundayken kızılötesi sensör \'Engel Algılandı\' sinyali üretirse güvenlik açısından hangi geçiş tasarlanmalıdır?', 'Doğrudan \'Açılıyor\' durumuna geçiş yapılmalıdır', ['Önce \'Kapalı\' durumuna geçip kilitlendikten sonra \'Açık\' durumuna atlanmalıdır', 'Sensör sinyali yok sayılarak mevcut \'Kapanıyor\' durumunda beklenmelidir', 'Sistem tuzak durumuna alınarak tüm kat butonları devre dışı bırakılmalıdır'], 'Sıkışmayı önlemek için \'Kapanıyor\' durumunda engel algılandığında motor yönü tersine çevrilerek \'Açılıyor\' durumuna geçilir.'),
  ('Bir DFA\'da q0 başlangıç durumu kabul durumu DEĞİLSE bu otomatın tanıdığı dil hakkında aşağıdakilerden hangisi kesinlikle doğrudur?', 'Boş dizge (ε) bu dilin bir elemanı değildir', ['Otomat sonlu sayıda dizgeden fazlasını kesinlikle kabul edemez', 'Otomatın tanıdığı dil boş küme olmak zorundadır', 'Girdi alfabesinde en az üç farklı sembol bulunmalıdır'], 'Boş dizge okunduğunda hiç geçiş yapılmadan q0\'da kalınır; dolayısıyla ε ∈ L olması ancak ve ancak q0 ∈ F olmasıyla mümkündür.'),
  ('Chomsky hiyerarşisinde sonlu durum otomatlarının tanıdığı \'Düzenli Diller\' hangi tip gramer sınıfına karşılık gelir?', 'Tip-3 (Sağdan veya soldan doğrusal gramerler)', ['Tip-2 (Bağlamdan bağımsız gramerler)', 'Tip-1 (Bağlama duyarlı gramerler)', 'Tip-0 (Kısıtlamasız özyinelemeli numaralanabilir gramerler)'], 'Chomsky hiyerarşisinde Tip-3 düzenli dilleri (FSM), Tip-2 bağlamdan bağımsız dilleri (PDA), Tip-1 bağlama duyarlı dilleri (LBA), Tip-0 ise Turing makinelerini kapsar.'),
  ('{a, b} alfabesinde uzunluğu tek sayı olan tüm dizgeleri tanıyan en küçük DFA kaç durumdan oluşur ve kabul durumu hangisidir?', '2 durumdan oluşur; başlangıç olmayan ikinci durum kabul durumudur', ['3 durumdan oluşur; hem birinci hem üçüncü durum kabul durumudur', '2 durumdan oluşur; yalnızca başlangıç durumu kabul durumudur', '1 durumdan oluşur; her harfte kendi üzerine dönen durum kabul durumudur'], 'q_cift (başlangıç, uzunluk 0,2,4...) ve q_tek (kabul, uzunluk 1,3,5...); alfabedeki her harf iki durum arasında karşılıklı geçiş yaptırır.'),
  ('Yığınlı otomat (Pushdown Automaton - PDA) sonlu durum makinesine hangi veri yapısını ekleyerek \'a^n b^n\' ve dengeli parantez dillerini tanıyabilir hale gelir?', 'Son giren ilk çıkar (LIFO) mantığıyla çalışan sınırsız bir yığın (stack) belleği', ['İki yönde sonsuz hareket edebilen ve üzerine yazılabilen rastgele erişimli bant', 'İlk giren ilk çıkar (FIFO) mantığıyla çalışan sabit boyutlu dairesel kuyruk', 'Anahtar-değer çiftlerini O(1) sürede saklayan özet (hash) tablosu'], 'Sonlu durum otomatına tek bir LIFO yığını eklendiğinde bağlamdan bağımsız dilleri tanıyan yığınlı otomat (PDA) elde edilir.'),
  ('Bir kelime işlemcide \'Cümle Düzeni\' (her noktadan sonraki ilk harfi büyütme) özelliğini gerçekleştiren durum makinesi \'Büyük Harf Bekleniyor\' durumunda başlar. Noktadan sonra gelen boşluk karakteri bu durumu nasıl etkilemelidir?', 'Durumu değiştirmeden \'Büyük Harf Bekleniyor\' durumunda bırakmalıdır ki boşluktan sonraki ilk harf büyütülsün', ['Boşluğu cümlenin ilk karakteri sayarak hemen \'Küçük Harf Modu\' durumuna geçirmelidir', 'Noktadan sonra boşluk gelmesini hata kabul ederek önceki kelimeyi silmelidir', 'Tüm paragrafı büyük harfe çeviren kalıcı kilit durumuna geçirmelidir'], '\'. merhaba\' metninde noktadan sonraki boşluk harf değildir; makine ilk gerçek harfi görene dek \'Büyük Harf Bekleniyor\' durumunda beklemeli, \'m\'yi \'M\' yapınca normal duruma geçmelidir.'),
  ('Bir e-ticaret siparişinin yaşam döngüsü \'Oluşturuldu -> Ödendi -> Kargolandı -> Teslim Edildi\' ve \'İptal Edildi\' durumlarıyla modellenmiştir. İş kuralına göre \'Kargolandı\' durumuna geçtikten sonra doğrudan \'İptal Edildi\' geçişine izin verilmemesi FSM\'de nasıl sağlanır?', '\'Kargolandı\' durumundan \'İptal Et\' olayı için \'İptal Edildi\'ye geçiş oku tanımlanmayarak', ['\'İptal Edildi\' durumunun çemberi çift çizgiyle çizilerek başlangıç durumu yapılarak', 'Tüm sipariş numaralarının düzenli ifadeyle kontrol edilmesi devre dışı bırakılarak', '\'Ödendi\' durumu ile \'Kargolandı\' durumu arasına sonsuz döngü eklenerek'], 'Durum makinesi modellemesinde geçersiz iş akışı geçişleri geçiş tablosundan çıkarılır; böylece kargodaki siparişe iptal isteği gelse bile sistem durum kuralını korur.'),
  ('Özyinelemeli (recursive) bir fonksiyonun sonsuz çağrı döngüsüne girmesini engelleyen ve doğrudan sonuç döndürerek durmasını sağlayan koşula ne ad verilir?', 'Taban durum (base case)', ['İlerleme adımı (inductive step)', 'Çağrı yığını işaretçisi (stack pointer)', 'Sözdizimi muhafızı (syntax guard)'], 'Her özyinelemeli fonksiyon, problemi küçülterek sonunda özyineleme yapmadan yanıt veren en az bir taban duruma ulaşmalıdır.'),
  ('Taban durumu unutulmuş veya girdi değeri taban duruma hiç yaklaşmayan özyinelemeli bir fonksiyon çalıştırıldığında çalışma zamanında hangi hata meydana gelir?', 'Yığın taşması (Stack Overflow)', ['Sıfıra bölme hatası (Division by Zero)', 'Ölü kilitlenme (Deadlock)', 'Derleme zamanı tip uyuşmazlığı'], 'Her özyinelemeli çağrı bellekteki çağrı yığınına (call stack) yeni bir aktivasyon çerçevesi ekler; durma koşulu sağlanmazsa yığın belleği tükenir.'),
  ('Bir fonksiyonun her çağrısında yerel değişkenlerinin, parametrelerinin ve geri dönüş adresinin çağrı yığını üzerinde saklandığı bellek bloğuna ne denir?', 'Etkinleştirme kaydı / yığın çerçevesi (stack frame)', ['Sembol tablosu satırı (symbol table entry)', 'Sanal bellek sayfa tablosu (page table)', 'Dinamik öbek kümesi (heap segment)'], 'Yığın çerçevesi (activation record / stack frame), her fonksiyon çağrısının kendi bağımsız yerel değişken kopyalarını ve dönüş adresini tutmasını sağlar.'),
  ('Pozitif tam sayılar için tanımlanan f(n): \'eğer n <= 1 ise 1 döndür; değilse n + f(n - 2) döndür\' fonksiyonu f(7) çağrısı için hangi sonucu üretir?', '16', ['28', '15', '21'], 'f(7) = 7 + f(5) = 7 + 5 + f(3) = 7 + 5 + 3 + f(1) = 7 + 5 + 3 + 1 = 16 değerini döndürür.'),
  ('Bir geliştirici faktöriyel hesaplamak için \'if (n == 0) return 1; return n * fak(n - 1);\' yazdığında bu fonksiyona yanlışlıkla fak(-2) gönderilirse ne olur?', 'n değeri -3, -4 biçiminde sıfırdan uzaklaşarak yığın taşmasına yol açar', ['Fonksiyon negatif işareti yok sayarak doğrudan 2 değerini döndürür', 'Taban durum ilk adımda tetiklenerek geriye 1 sonucu çevrilir', 'Çarpma işlemi taşma bayrağını sıfırlayarak 0 sonucunu üretir'], 'Koşul yalnızca \'n == 0\' eşitliğini kontrol ettiği için -2\'den başlayıp birer azalan çağrılar 0\'a hiç uğramaz ve sonsuz özyinelemeye girer.'),
  ('Saf özyinelemeli Fibonacci fonksiyonunda aynı alt problemlerin tekrar tekrar hesaplanmasını önleyerek zaman karmaşıklığını O(n) düzeyine indiren özyinelemeli teknik hangisidir?', 'Not alma / önbellekleme (memoization)', ['Kuyruk silme (tail truncation)', 'Sözdizimsel budama (lexical pruning)', 'Karşılıklı dallanma (mutual branching)'], 'Memoization tekniğinde hesaplanan her fib(k) değeri bir tabloya kaydedilir ve aynı k tekrar istendiğinde O(1) sürede tablodan döndürülür.'),
  ('4 diskli bir Hanoi Kuleleri oyununu en az hamleyle çözen özyinelemeli algoritma toplam kaç disk taşıma hamlesi gerçekleştirir?', '15 hamle', ['16 hamle', '8 hamle', '31 hamle'], 'Minimum hamle sayısı 2^n - 1 formülüyle 2^4 - 1 = 16 - 1 = 15 olarak bulunur.'),
  ('İki fonksiyonun (örneğin ciftMi(n) fonksiyonunun tekMi(n-1)\'i, tekMi(n) fonksiyonunun da ciftMi(n-1)\'i çağırması) birbirini dönüşümlü çağırmasına ne ad verilir?', 'Dolaylı / karşılıklı özyineleme (indirect / mutual recursion)', ['İç içe özyineleme (nested recursion)', 'Doğrusal kuyruksuz özyineleme (linear non-tail recursion)', 'Anonim özyineleme (anonymous recursion)'], 'Bir fonksiyon doğrudan kendi adını çağırmak yerine başka bir fonksiyon üzerinden yeniden kendisine ulaşıyorsa buna karşılıklı (dolaylı) özyineleme denir.'),
  ('Özyinelemeli Öklid algoritması \'ebob(a, b): b == 0 ise a döndür; değilse ebob(b, a mod b) döndür\' ile ebob(48, 18) hesaplanırken taban durum dahil fonksiyon toplam kaç kez çağrılır?', '4 kez', ['2 kez', '3 kez', '6 kez'], 'Sırasıyla ebob(48, 18) -> ebob(18, 12) -> ebob(12, 6) -> ebob(6, 0) çağrıları yapılır ve 6 döndürülür; toplam 4 çağrı gerçekleşir.'),
  ('Özyinelemeli bir fonksiyonu özyineleme kullanmadan döngüsel (iteratif) bir koda genel bir yöntemle dönüştürmek gerektiğinde programcının açıkça hangi veri yapısını yönetmesi gerekir?', 'Yığın (Stack)', ['Kuyruk (Queue)', 'Öncelik kuyruğu (Min-Heap)', 'Ayrık küme (Disjoint-Set)'], 'Derleyicinin arka planda tuttuğu çağrı yığını (call stack), iteratif dönüşümde programcı tarafından açık bir LIFO yığın veri yapısıyla taklit edilir.'),
  ('İkili bir ağacın (binary tree) düğüm sayısını hesaplayan özyinelemeli \'say(dugum)\' fonksiyonunun doğru tanımı hangisidir?', 'dugum == null ise 0 döndür; değilse 1 + say(dugum.sol) + say(dugum.sag) döndür', ['dugum == null ise 1 döndür; değilse say(dugum.sol) + say(dugum.sag) döndür', 'dugum == null ise 0 döndür; değilse max(say(dugum.sol), say(dugum.sag)) döndür', 'dugum.sol == null ise 1 döndür; değilse 2 * say(dugum.sol) döndür'], 'Boş alt ağaçta 0 düğüm vardır; dolu düğümde ise kendisi (1) + sol alt ağacın düğüm sayısı + sağ alt ağacın düğüm sayısı toplanır.'),
  ('Dosya sistemindeki bir klasörün ve içindeki tüm alt klasörlerin toplam bayt boyutunu hesaplamak için neden sabit sayıda iç içe \'for\' döngüsü yerine özyineleme (veya yığın/kuyruk) tercih edilir?', 'Alt klasörlerin kaç katman derinliğe kadar ineceği derleme zamanında önceden bilinemeyeceği için', ['İşletim sistemi API\'leri klasör listesini döngüler içinde okumaya güvenlik izni vermediği için', 'Özyinelemeli fonksiyonlar sabit diskten veri okuma hızını donanımsal olarak ikiye katladığı için', 'Dosya boyutları 64 bit tam sayı sınırını aştığında yalnızca yığın çerçevelerinde saklanabildiği için'], 'Sabit k adet iç içe döngü en fazla k seviye alt klasöre inebilir; özyineleme ise keyfi derinlikteki ağaçsal (hiyerarşik) veri yapılarını doğal biçimde dolaşır.'),
  ('Birbirinden farklı n karakterden oluşan bir dizgenin tüm permütasyonlarını (sıralamalarını) üreten özyinelemeli bir algoritma n = 4 için kaç adet yaprak çözüm üretir?', '24', ['16', '12', '64'], 'İlk konuma 4, ikinciye 3, üçüncüye 2, sonuncuya 1 seçenek kaldığından 4! = 24 farklı permütasyon üretilir.'),
  ('Pozitif bir tam sayının basamakları toplamını bulan özyinelemeli \'basamakToplam(n)\' fonksiyonu onluk tabanda nasıl yazılır?', 'n < 10 ise n döndür; değilse (n % 10) + basamakToplam(n // 10) döndür', ['n == 0 ise 1 döndür; değilse (n // 10) + basamakToplam(n % 10) döndür', 'n < 10 ise 0 döndür; değilse 1 + basamakToplam(n - 10) döndür', 'n <= 1 ise n döndür; değilse (n % 2) + basamakToplam(n // 2) döndür'], '\'n % 10\' birler basamağını ayırır, \'n // 10\' ise kalan basamakları küçültülmüş alt problem olarak özyinelemeye gönderir.'),
  ('Bir dizgenin palindrom (baştan ve sondan okunuşu aynı, örneğin \'KABAK\') olup olmadığını denetleyen özyinelemeli fonksiyonun her adımda yaptığı işlem nedir?', 'İlk ve son karakter eşitse her iki uçtan birer karakter kırpılmış iç alt dizge üzerinde özyineleme yapmak', ['Dizgeyi ortadan ikiye bölüp her iki yarının ayrı ayrı palindrom olup olmadığını kontrol etmek', 'Yalnızca ilk iki karakteri karşılaştırıp geri kalan dizgeyi sağa bir birim kaydırmak', 'Dizgenin uzunluğu çift sayı ise doğrudan doğru, tek sayı ise doğrudan yanlış döndürmek'], 'Taban durum uzunluk <= 1 (doğru); aksi halde s[0] == s[son] ise palindrom(s[1..son-1]) çağrılır, eşit değilse hemen yanlış döndürülür.'),
  ('Ağaç yapılı JSON veya iç içe liste verisini (örneğin \'[1, [2, [3, 4], 5], 6]\') tek boyutlu düz bir listeye (\'[1, 2, 3, 4, 5, 6]\') çeviren işleme ve doğal çözüm yöntemine ne denir?', 'Düzleştirme (flattening); eleman liste ise özyinelemeli düzleştir, atomik değerse sonuca ekle', ['Sıralı birleştirme (merging); yalnızca ilk ve son elemanları takas ederek kuyruğa ekle', 'Sözcüksel bölme (tokenizing); köşeli parantez sayısını ikiye bölerek orta elemanı seç', 'Sabit katlama (folding); iç listelerdeki tüm sayıları birbiriyle çarparak tek sayıya indir'], 'Derinliği düzensiz iç içe listeleri düzleştirmede her öğenin tipine bakılır: temel öğe ise listeye eklenir (taban durum), alt liste ise özyinelemeli olarak açılır.'),
  ('Koch Kar Tanesi veya Sierpinski Üçgeni gibi fraktal şekilleri ekrana çizen özyinelemeli grafik fonksiyonlarında \'derinlik (seviye)\' parametresinin görevi nedir?', 'Matematiksel olarak sonsuz olan öz-benzer bölünmeyi sonlu bir adımda durdurarak taban çizgiyi çizdirmek', ['Ekran çözünürlüğünün renk paletini siyah-beyazdan 32 bit renkli moda geçirmek', 'Çizilen üçgenlerin iç açılarının toplamını her adımda 180 derecenin üzerine çıkarmak', 'Grafik kartının bellek adreslerini özyineleme olmadan doğrudan diske kaydetmek'], 'Fraktallar kuramsal olarak sonsuz öz-benzerdir; yazılımda \'derinlik == 0\' taban durumuyla bölünme durdurulup düz doğru parçası çizilir.'),
  ('Bir ikili arama ağacında (BST) düğümleri \'Sol alt ağaç -> Kök -> Sağ alt ağaç\' (In-order / İç-sıralı) sırasıyla özyinelemeli dolaşan bir fonksiyon anahtarları hangi düzende üretir?', 'Küçükten büyüğe doğru sıralı düzende', ['Büyükten küçüğe doğru azalan düzende', 'Kökten yapraklara doğru seviye seviye düzende', 'Yapraklardan köke doğru silme düzeninde'], 'BST özelliğine göre soldaki tüm elemanlar kökten küçük, sağdakiler kökten büyüktür; bu yüzden Sol -> Kök -> Sağ özyinelemesi elemanları artan sırada verir.'),
  ('f(x, y) fonksiyonu negatif olmayan tam sayılar için \'x == 0 ise y döndür; değilse f(x - 1, y + 1) döndür\' şeklinde yazılmıştır. Bu fonksiyon ne hesaplar ve kuyruk özyinelemeli midir?', 'x + y toplamını hesaplar ve dönüş değerine ek işlem uygulanmadığı için kuyruk özyinelemelidir', ['x * y çarpımını hesaplar ve iki parametreli olduğu için kuyruk özyinelemeli değildir', 'x - y farkını hesaplar ve her adımda y büyüdüğü için sonsuz döngüye girer', 'x^y üssünü hesaplar ve O(log x) derinlikte sonlanır'], 'x her adımda 1 azalırken y 1 artar, dolayısıyla x + y değişmezi korunur ve x = 0 olduğunda y = x_ilk + y_ilk döner; son işlem doğrudan çağrı olduğu için kuyruk özyinelemelidir.'),
  ('g(n) fonksiyonu \'eğer n <= 0 ise 0 döndür; değilse n + g(n - 1) döndür\' şeklinde tanımlanmıştır. g(10) çağrısının döndürdüğü değer nedir?', '55', ['45', '100', '10'], '1\'den 10\'a kadar olan ardışık tam sayıların toplamı n(n+1)/2 = 10 * 11 / 2 = 55 değerini verir.'),
  ('Ters Polonya Gösterimi (Reverse Polish Notation - RPN / Sonek Gösterimi) ifadelerinin en belirgin sözdizimsel avantajı nedir?', 'Operatör önceliği kurallarına ve hiçbir gruplama parantezine ihtiyaç duymadan işlem sırasını tek ve kesin biçimde belirtmesi', ['Ondalıklı sayıların yuvarlama hatası olmadan sonsuz duyarlılıkta saklanmasını sağlaması', 'İfadelerin yığın belleği kullanılmadan yalnızca sağdan sola doğru tek yazmaçla çözülmesi', 'Değişken adlarının veri tiplerini çalışma zamanında otomatik olarak doğrulaması'], 'Sonek (postfix / RPN) ve önek (prefix) gösterimlerinde her operatör işleneceği tam konumda yer aldığından parantez belirsizliği tamamen ortadan kalkar.'),
  ('İçtakı (infix) biçiminde verilen \'3 + 4 * 5\' aritmetik ifadesinin Ters Polonya Gösterimi (RPN / postfix) karşılığı hangisidir?', '3 4 5 * +', ['3 4 + 5 *', '+ 3 * 4 5', '3 4 * 5 +'], 'Çarpmanın toplama üzerinde önceliği olduğundan önce \'4 * 5\' soneke çevrilir (\'4 5 *\'), ardından \'3\' ile toplanır: \'3 4 5 * +\'.'),
  ('İçtakı biçimindeki \'(3 + 4) * 5\' ifadesi Ters Polonya Gösterimine (RPN) çevrildiğinde aşağıdakilerden hangisi elde edilir?', '3 4 + 5 *', ['3 4 5 * +', '(3 4 +) 5 *', '* + 3 4 5'], 'Parantez toplama işlemini önce yaptırdığı için \'3 4 +\' oluşturulur, çıkan sonuç \'5\' ile çarpılmak üzere \'3 4 + 5 *\' yazılır ve parantezler atılır.'),
  ('RPN biçimindeki \'20 4 2 - / 3 *\' ifadesi soldan sağa değerlendirildiğinde sonuç kaç bulunur?', '30', ['9', '10', '48'], '\'4 2 -\' = 2 (yığın: 20, 2); \'/\' ile 20 / 2 = 10 (yığın: 10); \'3 *\' ile 10 * 3 = 30 bulunur.'),
  ('Edsger Dijkstra tarafından geliştirilen ve içtakı (infix) ifadeleri sonek (RPN) biçimine veya soyut sözdizimi ağacına dönüştüren yığın tabanlı algoritmanın adı nedir?', 'Manevra İstasyonu (Shunting-yard) algoritması', ['Altküme Kurulumu (Subset Construction) algoritması', 'Thompson Eşleştirme algoritması', 'Bellman-Ford Gevşetme algoritması'], 'Tren vagonlarının yan hatta bekletilip sıralanmasından esinlenen Dijkstra\'nın Shunting-yard algoritması, operatörleri öncelik ve birleşme yönüne göre bir operatör yığınında bekletir.'),
  ('Manevra İstasyonu (Shunting-yard) algoritmasında girdi jetonları soldan sağa okunurken bir sayı (işlenen / operand) görüldüğünde ne yapılır?', 'Bekletilmeden doğrudan çıktı kuyruğuna (RPN dizisine) eklenir', ['Kapanış parantezi gelene kadar operatör yığınının en altına itilir', 'Bir önceki sayıyla çarpılarak geçici bir yazmaçta biriktirilir', 'Öncelik tablosunda operatörlerden daha düşük sayıldığı için en sona bırakılır'], 'İçtakıdan soneke dönüşümde işlenenlerin (sayı ve değişkenlerin) birbirine göre göreli sırası hiç değişmez; yalnızca operatörlerin konumu yığınla kaydırılır.'),
  ('Yığın kullanarak dizgedeki çoklu parantez türlerinin — \'()\', \'[]\', \'{}\' — dengeli olup olmadığını denetleyen bir algoritma \'([)]\' girdisini neden reddeder?', '\'[\' karakterinden sonra \')\' geldiğinde yığının tepesinde \'(\' değil \'[\' bulunduğu için çapraz örtüşme hatası yakalanır', ['Açılış parantezlerinin toplam sayısı kapanış parantezlerinin toplam sayısına eşit olmadığı için', 'Köşeli parantezlerin yuvarlak parantezlerin içinde kullanılması matematiksel olarak yasak olduğu için', 'Dizgenin uzunluğu çift sayı olduğu için yığın sonunda fazladan iki eleman kaldığı için'], 'Sadece sayaç tutmak \'([)]\' hatasını kaçırır (bir \'(\' bir \')\', bir \'[\' bir \']\' var!); LIFO yığını ise en son açılan \'[\' parantezinin en ilk kapanması gerektiğini denetler.'),
  ('Aşağıdaki içtakı ifadelerden hangisinin RPN karşılığı \'a b + c d - /\' dizgesidir?', '(a + b) /', ['a + b / c - d', 'a + (b / c) - d', '(a + b / c) - d'], '\'a b +\' -> (a + b) sol alt ağaç, \'c d -\' -> (c - d) sağ alt ağaçtır; sondaki \'/\' ikisini böler: \'(a + b) / (c - d)\'.'),
  ('RPN biçimindeki \'a b c * + d +\' ifadesini gereksiz parantez kullanmadan en yalın içtakı (infix) biçime geri çevirdiğimizde hangi ifade elde edilir?', 'a + b * c + d', ['(a + b) *', '(a + b) * c + d', 'a * b + c + d'], '\'b c *\' çarpma önceliğiyle parantezsiz \'b * c\' olur; \'a\' ile toplanıp \'d\' eklendiğinde \'a + b * c + d\' aynı anlamı taşır.'),
  ('PostScript sayfa tanımlama dili ve klasik HP mühendislik hesap makineleri kullanıcı girdisini işlerken \'ENTER\' tuşunu \'=\' tuşu yerine nasıl kullanır?', '\'ENTER\' tuşu hesaplama yapmaz; yalnızca yazılan sayıyı sonlandırıp yığına iter, işlemi ise ardından basılan \'+\', \'*\' gibi operatör tuşları anında yapar', ['\'ENTER\' tuşu o ana kadar girilen tüm parantezli ifadeyi derleyip sonucu ekrana yazar', '\'ENTER\' tuşu yığının en üstündeki elemanı silerek belleği sıfırlar', '\'ENTER\' tuşu yalnızca değişken tanımlamak için kullanılır, sayılar boşluksuz birleşir'], 'RPN hesap makinelerinde \'3 [ENTER] 4 +\' tuşlamasında ENTER ilk sayıyı ikinci sayıdan ayırıp yığına iter; \'+\' basıldığı anda ek eşittir tuşuna gerek kalmadan sonuç 7 görünür.'),
  ('Derleyici nedir ve yorumlayıcıdan (interpreter) temel çalışma farkı hangisidir?', 'Kaynak kodu çalıştırmadan önce bütünüyle hedef dile (makine kodu veya bayt kodu) çeviren programdır; yorumlayıcı ise kodu adım adım okurken doğrudan yürütür', ['Yalnızca sözdizimi hatalarını düzelten metin editörüdür; yorumlayıcı ise kodu sıkıştırarak diske kaydeder', 'Kaynak kodu satır satır çalıştırıp çıktı üreten araçtır; yorumlayıcı ise çalıştırılabilir \'.exe\' dosyası oluşturur', 'Yalnızca donanım sürücülerini derleyen işletim sistemi çekirdeğidir; yorumlayıcı ise veritabanı sorgularını sıralar'], 'Derleyici (compiler) çeviri aşaması ile çalıştırma aşamasını ayırır; yorumlayıcı (interpreter) ise kaynak kodu veya ara temsili çalışma anında yürüterek çıktı üretir.'),
  ('Klasik çok aşamalı bir derleyicinin \'Ön Uç (Front-End)\' kısmında kaynak kod sırasıyla hangi üç temel analiz aşamasından geçer?', 'Sözcüksel Analiz (Lexical) -> Sözdizimi Analizi (Syntax / Parsing) -> Anlamsal Analiz', ['Sözdizimi Analizi -> Sözcüksel Analiz -> Makine Kodu Üretimi', 'Anlamsal Analiz -> Yazmaç Ataması -> Sözcüksel Analiz', 'Ara Kod Eniyilemesi -> Bağlama (Linking) -> Sözdizimi Analizi'], 'Derleyici ön ucu önce karakterleri jetonlara böler (lexer), sonra gramer ağacını kurar (parser) ve ardından tip/kapsam kurallarını denetler (semantic analyzer).'),
  ('Sözcüksel analizci (Lexer / Scanner) \'toplam = fiyat + 25;\' kaynak kod satırını okuduğunda Sözdizimi Analizcisine (Parser) ne aktarır?', 'Boşlukları temizleyip anlamlı dizgeciklerden oluşan jeton (token) akışını: [ID(\'toplam\'), ATAMA, ID(\'fiyat\'), ARTI, SAYI(25), NOKTALI_VİRGÜL]', ['İşlem önceliğine göre kurulmuş ve tipleri doğrulanmış ikili soyut sözdizimi ağacını', 'Hedef işlemcinin yazmaçlarına doğrudan yüklenebilen ikili makine kodu dizisini', 'Yalnızca satırdaki karakter sayısını ve noktalı virgülün bellek adresini'], 'Sözcüksel analizci ham karakter akışını düzenli ifadeler ve sonlu otomatlar yardımıyla jetonlara (token) dönüştürür, boşluk ve yorumları ayıklar.'),
  ('Kaynak kodda \'int saniye = 60 * 60 * 24;\' satırını gören bir derleyicinin çarpma işlemlerini çalışma zamanına bırakmak yerine derleme anında hesaplayıp koda doğrudan \'int saniye = 86400;\' yazmasına hangi eniyileme denir?', 'Sabit katlama (Constant Folding)', ['Döngü açma (Loop Unrolling)', 'Yazmaç dökümü (Register Spilling)', 'Dinamik bağlama (Dynamic Linking)'], 'Sabit işlenenlerden oluşan ifadelerin derleme zamanında hesaplanıp tek bir sabitle değiştirilmesine sabit katlama (constant folding) denir.'),
  ('Ayrı ayrı derlenmiş nesne dosyalarını (\'.o\' / \'.obj\') ve kütüphaneleri birleştirip dış fonksiyon/değişken referanslarını gerçek adreslerle eşleştirerek tek bir çalıştırılabilir dosya üreten sistem aracına ne ad verilir?', 'Bağlayıcı (Linker)', ['Önişlemci (Preprocessor)', 'Sözcüksel Tarayıcı (Scanner)', 'Soyutlayıcı (Serializer)'], 'Derleyici her kaynak dosyadan makine kodlu nesne dosyası üretir; dış modüllerdeki \'printf\' gibi çözülmemiş sembolleri birleştiren araç Bağlayıcıdır (Linker).'),
  ('C/C++ dillerinde \'#include\', \'#define\' ve \'#ifdef\' gibi yönergeleri işleyen Önişlemci (Preprocessor) derleme zincirinin tam olarak neresinde çalışır?', 'Sözcüksel analiz ve asıl derleme aşamalarından hemen önce, kaynak metin üzerinde metinsel ikame ve dosya ekleme yaparak', ['Makine kodu üretildikten hemen sonra nesne dosyalarını ikili düzeyde birleştirirken', 'Program belleğe yüklendikten sonra çalışma zamanında dinamik kütüphaneleri ararken', 'Soyut sözdizimi ağacı üzerinde yazmaç renklendirme eniyilemesi yapılırken'], 'Önişlemci C dilinin tip ve gramer kurallarını bilmez; derleyici çalışmadan önce makroları metinsel olarak açar ve başlık dosyalarını metne yapıştırır.'),
  ('Bir fonksiyonun kendi gövdesi içinden doğrudan veya dolaylı biçimde yeniden kendisini çağırması yöntemine ne ad verilir?', 'Özyineleme', ['Aşırı yükleme', 'Kapsülleme işlemi', 'Çok biçimlilik yapısı'], 'Bir alt programın problemi daha küçük alt problemlere indirgeyerek kendisini çağırmasına özyineleme (recursion) denir.'),
  ('Özyinelemeli bir fonksiyonda çağrı zincirinin sonsuza dek sürmesini engelleyen ve özyinelemeyi sonlandıran koşula ne ad verilir?', 'Taban durumu', ['Döngü değişmezi', 'Sözcüksel belirteç', 'Yığın taşma sınırı'], 'Taban durumu (base case), özyinelemeli çağrıların durup geriye değer döndürmeye başladığı temel koşuldur.'),
  ('Taban durumu unutulmuş veya hiçbir girdi için sağlanmayan özyinelemeli bir fonksiyon çalıştırıldığında çalışma zamanında hangi hata meydana gelir?', 'Yığın taşması hatası', ['Sözdizimi ayrıştırma hatası', 'Tür uyuşmazlığı istisnası', 'Sıfıra bölme belirsizliği'], 'Her fonksiyon çağrısı çağrı yığınında (call stack) yeni bir çerçeve açtığından durmayan özyineleme yığın taşmasına (stack overflow) yol açar.'),
  ('Program çalışırken aktif fonksiyon çağrılarının yerel değişkenlerini, parametrelerini ve dönüş adreslerini saklayan bellek yapısının adı nedir?', 'Çağrı yığını', ['Öncelik kuyruğu', 'Sembol tablosu', 'Komut önbelleği'], 'Aktif alt program çerçeveleri Son Giren İlk Çıkar (LIFO) ilkesiyle çalışan çağrı yığınında (call stack) tutulur.'),
  ('f(0) = 1 ve n > 0 için f(n) = n * f(n - 1) olarak tanımlanan özyinelemeli fonksiyon için f(4) çağrısının döndürdüğü değer kaçtır?', '24', ['16', '10', '120'], 'f(4) = 4 * 3 * 2 * 1 * 1 = 24 olarak hesaplanır.'),
  ('g(0) = 0 ve n > 0 için g(n) = n + g(n - 1) biçiminde tanımlanan özyinelemeli fonksiyon için g(5) çağrısının sonucu kaçtır?', '15', ['10', '20', '25'], 'g(5) = 5 + 4 + 3 + 2 + 1 + 0 = 15 sonucunu üretir.'),
  ('A fonksiyonunun B fonksiyonunu, B fonksiyonunun da yeniden A fonksiyonunu çağırdığı özyineleme türüne ne ad verilir?', 'Karşılıklı özyineleme', ['İç içe özyineleme', 'Doğrudan özyineleme', 'Tekil kuyruk çağrısı'], 'İki veya daha fazla fonksiyonun döngüsel olarak birbirini çağırmasına karşılıklı (dolaylı) özyineleme denir.'),
  ('Özyinelemeli bir algoritmanın döngüler kullanılarak özyinelemesiz biçimde yeniden yazılması işleminde, derleyicinin örtük olarak kullandığı hangi veri yapısı programcı tarafından açıkça yönetilebilir?', 'Yığın (stack)', ['Kuyruk (queue)', 'Çırpı tablosu (hash table)', 'Ayrık küme (disjoint set)'], 'Çağrı yığınının LIFO davranışını taklit etmek için özyinelemeden döngüye geçişte açık bir yığın (stack) veri yapısı kullanılır.'),
  ('Aritmetik ifadelerde işlecin (operatörün) iki işlenenin (operandın) tam arasına yazıldığı "A + B" biçimindeki gösterime ne ad verilir?', 'İnfix (orta ek) gösterimi', ['Prefix (ön ek) gösterimi', 'Postfix (son ek) gösterimi', 'Kanonik normal gösterim'], 'Günlük matematikte kullanılan ve operatörün işlenenlerin ortasında yer aldığı gösterim infix gösterimidir.'),
  ('Parantez gerektirmeden işleçlerin işlenenlerden hemen sonra yazıldığı "A B +" biçimindeki gösterimin literatürdeki yaygın adı nedir?', 'Ters Lehçe Gösterimi (RPN / Postfix)', ['Lehçe Gösterimi (Prefix)', 'Macar Gösterimi (Hungarian)', 'Genişletilmiş Backus-Naur Gösterimi'], 'Jan Lukasiewicz\'in Lehçe gösteriminin tersi olan postfix yazımına Ters Lehçe Gösterimi (Reverse Polish Notation - RPN) denir.'),
  ('İşleçlerin işlenenlerinin hemen önüne yazıldığı "+ A B" biçimindeki matematiksel ifade gösterimine ne ad verilir?', 'Prefix (Lehçe) gösterimi', ['İnfix (orta ek) gösterimi', 'Postfix (Ters Lehçe) gösterimi', 'Üç adresli ara kod gösterimi'], 'Operatörün operandlardan önce geldiği parantezsiz gösterim prefix (Polish notation) olarak adlandırılır.'),
  ('Prefix ve postfix ifade gösterimlerinin derleyiciler ve hesap makineleri açısından infix gösterime göre en önemli yapısal üstünlüğü nedir?', 'İşlem önceliği belirsizliği taşımadan parantezsiz değerlendirilebilmeleri', ['İşlenen sayısını yarıya indirerek ifadeyi daha az karakterle yazmaları', 'Yalnızca tek basamaklı tam sayılarla çalışmaya olanak tanımaları', 'Değişme özelliği olmayan çıkarma ve bölme işlemlerini ortadan kaldırmaları'], 'Prefix ve postfix ifadelerde işlem sırası konumla kesinleştiği için paranteze ve öncelik tablosuna gerek kalmaz.'),
  ('"3 + 4 * 5" infix ifadesinin standart işlem önceliğine göre postfix (RPN) karşılığı aşağıdakilerden hangisidir?', '3 4 5 * +', ['3 4 + 5 *', '+ 3 * 4 5', '3 4 * 5 +'], 'Çarpma toplamadan öncelikli olduğundan önce 4 ile 5 çarpılır (4 5 *), sonra 3 ile toplanır: 3 4 5 * +.'),
  ('"(3 + 4) * 5" infix ifadesinin postfix (RPN) gösterimindeki karşılığı aşağıdakilerden hangisidir?', '3 4 + 5 *', ['3 4 5 * +', '* + 3 4 5', '3 5 * 4 +'], 'Parantez içindeki toplama önce değerlendirileceğinden 3 4 + yazılır, ardından 5 ile çarpılır: 3 4 + 5 *.'),
  ('Bir aritmetik ifade ağacında (expression tree) yaprak düğümler ve iç düğümler sırasıyla hangi bileşenleri temsil eder?', 'Yapraklar işlenenleri (sayı/değişken), iç düğümler işleçleri (operatörleri)', ['Yapraklar işleçleri (operatörleri), iç düğümler işlenenleri (sayıları)', 'Yapraklar parantez çiftlerini, iç düğümler atama deyimlerini', 'Yapraklar veri tiplerini, iç düğümler yalnızca karşılaştırma sinyallerini'], 'İfade ağaçlarında sayılar ve değişkenler çocuksuz yapraklarda, onları birleştiren operatörler ise iç düğümlerde yer alır.'),
  ('"9 5 - 2 *" postfix ifadesinin parantezli tam eşdeğer infix yazılışı aşağıdakilerden hangisidir?', '(9 - 5) * 2', ['9 -', '(9 * 2) - 5', '2 -'], 'Önce 9\'dan 5 çıkarılıp sonuç 2 ile çarpıldığı için eşdeğer infix ifade (9 - 5) * 2 olur.'),
  ('Yığın tabanlı sanal makinelerde (örneğin JVM bayt kodu veya WebAssembly yığın makinesi) aritmetik komutların çoğunlukla hangi ifade modeline göre çalıştığı söylenebilir?', 'Postfix (RPN) yığın değerlendirme modeline göre', ['Tam parantezli metinsel infix modeline göre', 'Sağdan sola prefix tarama modeline göre', 'Rastgele erişimli tablo birleştirme modeline göre'], 'Yığın makinelerinde önce operandlar yığına itilir (push), ardından gelen aritmetik komut (örneğin iadd) yığından çekip sonucu iter; bu tam olarak postfix modelidir.'),
  ('"+ 12 * 3 5" prefix ifadesinin sayısal sonucu kaçtır?', '27', ['75', '20', '63'], 'Önce (* 3 5) = 15 hesaplanır, ardından (+ 12 15) = 27 bulunur.'),
  ('Chomsky hiyerarşisinde programlama dillerinin sözdizimini (syntax) tanımlamak için en yaygın kullanılan gramer sınıfı hangisidir?', 'Bağlamdan bağımsız gramerler (Tip-2)', ['Düzenli (regular) gramerler (Tip-3)', 'Bağlama duyarlı gramerler (Tip-1)', 'Kısıtsız özyinelemeli gramerler (Tip-0)'], 'Programlama dillerinin iç içe blok ve parantez yapıları Tip-2 olan bağlamdan bağımsız gramerlerle (CFG) modellenir.'),
  ('Biçimsel bir bağlamdan bağımsız gramer (CFG) matematiksel olarak hangi dörtlü bileşen kümesiyle (G = (V, Σ, R, S)) tanımlanır?', 'Değişkenler (uçbirim olmayanlar), uçbirim simgeler, üretim kuralları ve başlangıç simgesi', ['Durumlar kümesi, giriş alfabesi, geçiş tablosu ve kabul durumları kümesi', 'Yazmaçlar kümesi, bellek adresleri, makine komutları ve yığın işaretçisi', 'Anahtar sözcükler, yorum satırları, veri tipleri ve çalışma zamanı yığını'], 'Bir CFG; uçbirim olmayan simgeler (V), uçbirim simgeler (Σ), üretim kuralları (R) ve başlangıç simgesinden (S) oluşur.'),
  ('Bir bağlamdan bağımsız gramerde başka simgelere türetilemeyen ve doğrudan dilin dizgilerinde yer alan temel simgelere ne ad verilir?', 'Uçbirim (terminal) simgeler', ['Uçbirim olmayan (non-terminal) simgeler', 'Başlangıç aksiyom değişkenleri', 'Sentezlenmiş öznitelik düğümleri'], 'Türetme sonunda dizgiyi oluşturan ve sol tarafta tek başına kural tanımlanmayan simgelere uçbirim (terminal) simgeler denir.'),
  ('Programlama dillerinin bağlamdan bağımsız sözdizimi kurallarını metinsel olarak ifade etmek için John Backus ve Peter Naur tarafından geliştirilen gösterimin kısaltması nedir?', 'BNF (Backus-Naur Formu)', ['AST (Soyut Sözdizimi Ağacı)', 'SSA (Statik Tekil Atama)', 'JIT (Tam Zamanında Derleme)'], 'Dil gramerlerini <ifade> ::= <terim> + <ifade> biçiminde tanımlayan standart gösterim Backus-Naur Formudur (BNF).'),
  ('Kaynak kodun tamamını çalıştırılmadan önce analiz edip hedef makine koduna veya alt seviye koda çeviren sistem yazılımına ne ad verilir?', 'Derleyici (compiler)', ['Yorumlayıcı (interpreter)', 'Bağlayıcı yükleyici (loader)', 'Paket yöneticisi (package manager)'], 'Kaynak programı bütün olarak hedef koda dönüştüren çevirici yazılıma derleyici denir.'),
  ('Kaynak kodu veya ara kodu ayrı bir makine kodu yürütülebilir dosyası üretmeden deyim deyim okuyup doğrudan çalıştıran yazılıma ne ad verilir?', 'Yorumlayıcı (interpreter)', ['Önişlemci (preprocessor)', 'Çevirici birleştirici (assembler)', 'Statik bağlayıcı (static linker)'], 'Kodu satır/deyim bazında analiz ederek anında yürüten yazılım yorumlayıcıdır.'),
  ('Derleyicinin ilk aşaması olan sözcüksel çözümleyicinin (lexer / scanner) temel görevi nedir?', 'Ham karakter akışını okuyup anlamlı belirteç (token) dizisine dönüştürmek ve boşluk/yorumları ayıklamak', ['Belirteçlerin veri tiplerini karşılaştırıp örtük tür dönüşümlerini gerçekleştirmek', 'Soyut sözdizimi ağacı üzerinde döngü eniyileştirmeleri uygulayarak hızı artırmak', 'Hedef işlemci mimarisinin yazmaçlarını değişkenlere en az taşmayla atamak'], 'Lexer karakterleri gruplayarak anahtar sözcük, tanıtıcı, sabit ve işleç gibi belirteçlere (token) dönüştürür.'),
  ('Sözcüksel çözümleyicinin kurallarını tanımlamak ve belirteç kalıplarını eşleştirmek için hangi biçimsel araç kullanılır?', 'Düzenli ifadeler (regular expressions) ve sonlu durum otomatları', ['Yığınlı otomatlar ve bağlama duyarlı üretim kuralları', 'Statik tekil atama çizgeleri ve girişim grafikleri', 'Çalışma zamanı profilleyicileri ve çöp toplayıcılar'], 'Belirteç yapıları düzenli dillerle ifade edilir; lexer üreteçleri düzenli ifadeleri sonlu otomatlara (NFA/DFA) çevirir.'),
  ('Kaynaktaki int 3sayi = 10; ifadesinde değişken adının rakamla başlaması nedeniyle hata verilmesi derleyicinin hangi aşamasında gerçekleşir?', 'Sözcüksel çözümleme (lexical analysis) aşamasında', ['Hedef kod üretimi (code generation) aşamasında', 'Çalışma zamanı JIT derleme aşamasında', 'Statik kütüphane bağlama (linking) aşamasında'], '3sayi geçerli bir sayı veya tanıtıcı belirteç kalıbına uymadığı için sözcüksel çözümleyici (lexer) tarafından geçersiz belirteç olarak yakalanır.'),
  ('Derleyicide sözcüksel çözümleyiciden gelen belirteç (token) dizisinin dilin gramer kurallarına uygunluğunu denetleyen ve ağaç yapısını kuran bileşen hangisidir?', 'Sözdizimi çözümleyicisi (parser)', ['Önişlemci makro genişleticisi', 'Bağlayıcı (linker) modülü', 'Çöp toplayıcı (garbage collector)'], 'Parser belirteç akışını gramer kurallarına göre ayrıştırarak sözdizimsel yapıyı doğrular.'),
  ('Derleme sürecinde değişkenlerin, fonksiyonların ve sınıfların adlarını, veri tiplerini, kapsam (scope) düzeylerini ve bellek konum bilgilerini kaydeden veri yapısına ne ad verilir?', 'Sembol tablosu (symbol table)', ['Komut önbelleği (instruction cache)', 'Kesme vektör tablosu (interrupt table)', 'Sayfa çerçeve tablosu (page table)'], 'Derleyicinin bildirimleri ve kapsam bilgilerini takip etmek için kullandığı merkezi sözlük yapısı sembol tablosudur.'),
  ('Sözdizimi tamamen doğru olan int x = "merhaba"; deyiminin geçersiz sayılarak reddedilmesi derleyicinin hangi aşamasının sorumluluğundadır?', 'Anlamsal çözümleme ve tip denetimi (semantic analysis / type checking)', ['Sözcüksel belirteç ayırma (lexical scanning)', 'Makineye bağımlı yazmaç tahsisi (register allocation)', 'Bağlayıcı adres çözümleme (linker relocation)'], 'Atama sözdizimi (tip ad = deger;) gramerce geçerlidir; ancak metin sabitinin tam sayı değişkenine atanamayacağını tip denetleyicisi yakalar.'),
  ('Kaynak koddaki int saniye = 60 * 60 * 24; ifadesinin derleyici tarafından derleme zamanında hesaplanıp doğrudan int saniye = 86400; biçimine çevrilmesi hangi eniyileştirme tekniğidir?', 'Sabit katlama (constant folding)', ['Döngü açma (loop unrolling)', 'Fonksiyon satır içi açma (function inlining)', 'Ortak alt ifade elemesi (CSE)'], 'Derleme zamanında bilinen sabit ifadelerin önceden hesaplanarak tek bir sabitle değiştirilmesine sabit katlama denir.'),
  ('Programın çalışması sırasında sık yürütülen ara kod (bytecode) bölümlerini tespit edip o anda yerel makine koduna derleyerek hızlandıran tekniğin adı nedir?', 'Tam Zamanında Derleme (JIT - Just-In-Time Compilation)', ['Önceden Tam Derleme (AOT - Ahead-Of-Time Compilation)', 'Sözcüksel Önişleme (Lexical Preprocessing)', 'Statik Bağlama (Static Linking)'], 'JVM, .NET CLR ve V8 gibi çalışma zamanlarında sıcak kodları çalışma anında makine koduna çeviren teknoloji JIT derlemedir.'),
  ('Kaynak kodda açılan bir süslü parantezin } ile kapatılmasının unutulması derleyicinin hangi aşamasında hata olarak raporlanır?', 'Sözdizimi çözümlemesi (syntax analysis / parsing) aşamasında', ['Sözcüksel çözümleme (lexical analysis) aşamasında', 'Makineye bağımlı komut seçimi aşamasında', 'Çalışma zamanı çöp toplama aşamasında'], 'Tek başına { geçerli bir belirteçtir; ancak eşleşen } olmaması gramerin blok kuralını bozduğu için parser tarafından sözdizimi hatası olarak yakalanır.'),
  ('WebAssembly veya mobil uygulama mağazalarında olduğu gibi, kaynak veya ara kodun hedef cihazda çalıştırılmadan önce tamamen yerel makine koduna derlenmesi yaklaşımına ne ad verilir?', 'Önceden Derleme (AOT - Ahead-Of-Time Compilation)', ['Tam Zamanında Derleme (JIT Compilation)', 'Satır Satır AST Yorumlama (Tree-Walk Interpretation)', 'Çalışma Zamanı Yansıması (Runtime Reflection)'], 'Uygulama çalıştırılmadan önce makine kodunun üretilmesi AOT (Ahead-Of-Time) derleme olarak adlandırılır.'),
  ('Bir kaynak kod dosyasında yorum satırlarının (// açıklama) silinmesi veya yok sayılması derleme sürecinin hangi aşamasında gerçekleştirilir?', 'Sözcüksel çözümleme (lexer) aşamasında', ['Anlamsal tip çıkarımı aşamasında', 'Makine kodu yazmaç tahsisi aşamasında', 'Dinamik kütüphane yükleme aşamasında'], 'Yorum satırları ve anlamsız boşluklar sözcüksel çözümleyici tarafından elenir ve sözdizimi çözümleyicisine (parser) belirteç olarak gönderilmez.'),
];
